        raise HTTPException(status_code=404, detail="Sustainability record not found")

    return SustainabilityRead.model_validate(sustainability)


@router.delete("/{sustainability_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_sustainability(
    sustainability_id: uuid.UUID,
    current_user: User = Depends(require_any_role(Role.ADMIN, Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> None:
    success = soft_delete_sustainability_service(db, sustainability_id, current_user.id)
    if not success:
        raise HTTPException(status_code=404, detail="Sustainability record not found")


@router.get("/by-reference/{reference_id}", response_model=SustainabilityRead)
def get_sustainability_by_reference(
    reference_id: str,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> SustainabilityRead:
    sustainability = get_sustainability_service(db, reference_id)
    if not sustainability:
        raise HTTPException(status_code=404, detail="Sustainability record not found")

    return SustainabilityRead.model_validate(sustainability)

